<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {Camera,Send,Trash2,RefreshCw,Check,MessageCircle} from 'lucide-vue-next'
import {useSession} from './store'
import NutritionSource from './NutritionSource.vue'
import GuidanceSources from './GuidanceSources.vue'
function newRequestId(){return Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')}
const props=defineProps<{date:string;timezone:string;mode:string}>()
const emit=defineEmits<{updated:[];reviewLog:[log:any]}>()
const session=useSession(),turns=ref<any[]>([]),message=ref(''),share=ref(false),busy=ref(false),error=ref(''),imageData=ref(''),photoName=ref(''),fileInput=ref<HTMLInputElement|null>(null),requestId=ref(newRequestId())
const meal=ref('午餐'),photoDate=ref(props.date),photoTime=ref('12:00')
const meals=['早餐','午餐','晚餐','加餐']
function localISO(day:string,time:string){const desired=Date.parse(`${day}T${time}:00Z`);let guess=desired;for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:props.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess)).map(x=>[x.type,x.value]));guess+=desired-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)}return new Date(guess).toISOString()}
async function refresh(){turns.value=await session.api('/assistant/history')}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function loadPhoto(file?:File){if(!file)return;error.value='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('请上传 JPEG、PNG 或 WebP 图片');if(file.size>12*1024*1024)throw new Error('原图最大12MB，请压缩后上传');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();imageData.value=canvas.toDataURL('image/jpeg',.88);photoName.value=file.name;requestId.value=newRequestId()}catch(e:any){error.value=e.message}}
function pasteImage(event:ClipboardEvent){const f=Array.from(event.clipboardData?.files??[]).find(f=>f.type.startsWith('image/'));if(f){event.preventDefault();void loadPhoto(f)}}
async function send(text?:string){if(text)message.value=text;if(!message.value.trim()&&!imageData.value)return;await action(async()=>{
 if(props.mode==='live'&&!share.value)throw new Error('请先勾选本次模型处理授权')
 let result:any
 if(imageData.value){result=await session.api('/assistant/photos','POST',{revision:session.revision,request_id:requestId.value,image_data:imageData.value,message:message.value,meal:meal.value,eaten_at:localISO(photoDate.value,photoTime.value),share_context:share.value})}
 else{result=await session.api('/assistant/messages','POST',{date:props.date,message:message.value,share_context:share.value,request_id:requestId.value})}
 if(result.mode==='consent_required')throw new Error(result.summary)
 message.value='';imageData.value='';photoName.value='';requestId.value=newRequestId();share.value=false
 await refresh();emit('updated')
})}
async function decide(batch:any,confirm:boolean){await action(async()=>{await session.api(`/assistant/batches/${batch.batch_id}/${confirm?'confirm':'reject'}`,'POST');await refresh();emit('updated')})}
async function decideOne(p:any,confirm:boolean){await action(async()=>{await session.api(`/adjustments/${p.id}/${confirm?'confirm':'reject'}`,'POST');await refresh();emit('updated')})}
async function reviewPhoto(id:number){await action(async()=>{const log=await session.api('/food-logs/'+id);emit('reviewLog',log)})}
function foodsFor(p:any,meal:string){return p.items.filter((i:any)=>i.meal===meal).map((i:any)=>`${i.name} ${i.grams}g`).join('、')}
onMounted(()=>void action(refresh))
watch(()=>session.revision,()=>void refresh().catch((e:any)=>error.value=e.message))
watch(()=>props.date,v=>photoDate.value=v)
</script>
<template><section class="chat-panel">
 <div class="chat-heading"><MessageCircle :size="28"/><div><h2>聊近况，也能安排下一餐。</h2><p>照片先识别核对，多日计划确认后一起更新。</p></div><button class="icon-button" aria-label="刷新聊天记录" :disabled="busy" @click="action(refresh)"><RefreshCw :size="18"/></button></div>
 <div v-if="!turns.length" class="chat-empty"><h3>今天吃得怎么样？</h3><p>试试“这两天吃得有点多，帮我安排未来三天”。<br>也可以上传餐食照片，先得到一份待核对的记录。</p></div>
 <div class="chat-feed" aria-live="polite"><article v-for="turn in turns" :key="turn.id" class="chat-turn"><div class="user-bubble"><small>{{ turn.date }}</small><p>{{ turn.question }}</p></div><div class="assistant-bubble"><span class="tag">{{ turn.answer.mode==='live'?'DeepSeek':turn.answer.mode==='vision'?'照片识别':turn.answer.mode==='demo'?'规则演示':turn.answer.mode==='health_guidance'?'知识库参考':turn.answer.mode==='knowledge_fallback'?'知识库兜底':'本地提示' }}</span><p v-if="turn.answer.error" class="error">{{ turn.answer.error }}<small v-if="turn.answer.error_code">错误编号：{{ turn.answer.error_code }}</small></p><p class="chat-answer">{{ turn.answer.summary }}</p><p v-for="s in turn.answer.suggestions" :key="s">{{ s }}</p><GuidanceSources :sources="turn.answer.citations??[]"/><details v-if="turn.answer.known_facts?.length"><summary>已知事实与数据依据</summary><p v-for="f in turn.answer.known_facts">{{ f }}</p><small>记录不完整时，不能据此判断整日或连续多日的总摄入。</small></details><div v-if="turn.answer.uncertainties?.length" class="chat-uncertainties"><p v-for="u in turn.answer.uncertainties">{{ u }}</p></div>
 <section v-for="batch in turn.answer.batches" :key="batch.batch_id" class="chat-batch"><div class="section-head"><h3>{{ batch.proposals.length }} 天计划调整</h3><span class="pill">{{ batch.status==='confirmed'?'整组已生效':batch.status==='rejected'?'已拒绝':'等待确认' }}</span></div><details v-for="p in batch.proposals" :key="p.id" open><summary>{{ p.date }} · {{ p.before?'替换原计划 v'+p.before.version:'新建当天计划' }}</summary><div class="chat-day"><div v-if="p.before"><h4>原计划</h4><p v-for="m in meals"><strong>{{ m }}</strong> {{ foodsFor(p.before,m)||'无安排' }}</p></div><div><h4>建议计划</h4><p v-for="m in meals"><strong>{{ m }}</strong> {{ foodsFor(p,m)||'按需，不强制加餐' }}</p></div></div><small>{{ p.reason }}</small><details><summary>营养估算与来源</summary><NutritionSource v-for="item in p.items" :key="item.meal+'-'+item.food_id" :item="item"/></details></details><p v-if="batch.status==='pending'">是否应用这 {{ batch.proposals.length }} 天的计划？确认前，原计划保持不变。</p><p v-if="batch.status==='pending'&&batch.proposals[0].base_data_revision!==session.revision" class="error">记录或档案已更新，这组草案已过期。请重新让助手安排。</p><div v-if="batch.status==='pending'" class="actions"><button class="primary" :disabled="busy||batch.proposals[0].base_data_revision!==session.revision" @click="decide(batch,true)"><Check :size="16"/>确认未来 {{ batch.proposals.length }} 天计划</button><button :disabled="busy" @click="decide(batch,false)">暂不更改</button></div></section>
 <section v-for="p in turn.answer.proposals" :key="p.id" class="chat-batch"><h3>{{ p.date }} · 计划草案</h3><p>{{ p.reason }}</p><div class="chat-day"><div v-if="p.before"><h4>原计划</h4><p v-for="m in meals">{{ m }}：{{ foodsFor(p.before,m)||'无安排' }}</p></div><div><h4>建议计划</h4><p v-for="m in meals">{{ m }}：{{ foodsFor(p,m)||'无安排' }}</p></div></div><div v-if="p.status==='pending'" class="actions"><button class="primary" :disabled="busy||p.base_data_revision!==session.revision" @click="decideOne(p,true)">确认应用</button><button :disabled="busy" @click="decideOne(p,false)">拒绝草案</button></div><p v-else>{{ p.status==='confirmed'?'已应用':'已拒绝' }}</p><p v-if="p.status==='pending'&&p.base_data_revision!==session.revision" class="error">草案已过期，请重新生成。</p></section>
 <section v-if="turn.answer.photo_log_id" class="chat-photo-result"><h4>识别结果已保存到记录页</h4><small>以下保留首次识别结果；核对后的最终数据以记录页为准。</small><div v-for="(i,index) in turn.answer.recognized_items" :key="index"><p><strong>{{ i.name }}</strong> · {{ i.grams==null?'份量待填写':`估计 ${i.grams}g` }}</p><details><summary>匹配依据及营养来源</summary><NutritionSource :item="i"/></details></div><p>{{ turn.answer.photo_status==='confirmed'?'该记录已核对并计入已知摄入':turn.answer.photo_status==='deleted'?'该记录已删除':'待确认：尚未计入实际摄入，请核对份量、时间和是否吃完。' }}</p><button v-if="turn.answer.photo_status!=='deleted'" class="primary" :disabled="busy" @click="reviewPhoto(turn.answer.photo_log_id)">{{ turn.answer.photo_status==='confirmed'?'查看 / 修改记录':'核对并确认记录' }}</button></section>
 <details v-if="turn.answer.tool_trace?.length"><summary>工具调用记录</summary><small>{{ turn.answer.tool_trace.join(' → ') }}</small></details></div></article></div>
 <div class="quick-prompts"><button :disabled="busy" @click="message='这两天感觉吃得有点多，请结合记录安排未来三天，保持正常三餐。'">安排未来三天</button><button :disabled="busy" @click="message='帮我看看今天的饮食记录'">看看今天的记录</button><button :disabled="busy" @click="fileInput?.click()"><Camera :size="16"/>发餐食照片</button></div>
 <form class="chat-composer" @submit.prevent="send()" @dragover.prevent @drop.prevent="loadPhoto($event.dataTransfer?.files[0])"><div v-if="imageData" class="photo-preview"><img :src="imageData" alt="本次准备识别的餐食照片"><div><p>{{ photoName }}</p><small>上传前会缩小并去除原始元数据；照片不在本应用落盘保存。</small><button type="button" class="text-button" :disabled="busy" @click="imageData='';requestId=newRequestId()"><Trash2 :size="14"/>移除照片</button></div></div><div v-if="imageData" class="photo-fields"><label>就餐日期<input type="date" v-model="photoDate" required></label><label>餐次<select v-model="meal"><option v-for="m in meals">{{ m }}</option></select></label><label>时间（{{ timezone }}）<input type="time" v-model="photoTime" required></label></div><label class="sr-only" for="chat-message">向饮食助手发送消息</label><textarea id="chat-message" v-model="message"  :maxlength="imageData?1000:2000" :disabled="busy" @paste="pasteImage" placeholder="说说近况，或粘贴/拖入餐食照片。例如：最近吃得比较油，未来三天怎么安排？"></textarea><input class="sr-only" ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp" @change="loadPhoto(($event.target as HTMLInputElement).files?.[0]);($event.target as HTMLInputElement).value='' "><label v-if="mode==='live'||imageData" class="check-label"><input type="checkbox" v-model="share" :disabled="busy">允许本次向模型发送问题、最新基础档案（含已填写的身体信息与饮食限制）、最近6轮对话、必要饮食上下文及所选照片</label><p class="caption">照片份量和成分可能不准确；识别结果先存为待确认。聊天记录保存在你的账号中，可导出或随账号删除。</p><div class="actions"><button type="button" :disabled="busy" @click="fileInput?.click()"><Camera :size="17"/>添加照片</button><button type="submit" class="primary" :disabled="busy||(!message.trim()&&!imageData)"><Send :size="16"/>{{ busy?'正在分析…':imageData?'识别并保存待确认记录':'发送' }}</button></div><p v-if="busy" role="status" class="muted">正在读取上下文并生成建议，请稍候…</p><p v-if="error" role="alert" class="error">{{ error }}</p></form>
</section></template>
<style scoped>.assistant-bubble .chat-answer{white-space:pre-wrap;line-height:1.9;font-size:14px;font-weight:400;}.chat-panel{max-width:980px;margin:auto}.chat-heading{display:flex;align-items:center;gap:16px;margin:20px 0;color:#2557a7}.chat-heading p{font-size:12px;color:#62758d}.chat-heading>div{flex:1}.chat-empty{text-align:center;padding:40px 20px;color:#62758d}.chat-empty h3{color:#18304f;font-size:24px}.chat-turn{margin:25px 0}.user-bubble{background:#2557a7;color:white;border-radius:16px 16px 3px 16px;padding:13px 18px;margin-left:15%;overflow-wrap:anywhere}.user-bubble small{color:#d9e6fa}.assistant-bubble{background:white;border:1px solid #dae3ef;border-radius:3px 16px 16px 16px;padding:22px;margin:12px 4% 0 0;min-width:0}.assistant-bubble h3{margin-top:13px}.assistant-bubble p{font-size:13px}.chat-uncertainties{color:#62758d;border-left:3px solid #d9e6fa;padding-left:12px;margin:15px 0}.chat-uncertainties p{font-size:11px}.chat-batch,.chat-photo-result{background:#f5f8fc;padding:18px;margin:20px 0;border-radius:10px;border:1px solid #d3e0f1}.chat-batch>.section-head{margin:0 0 10px}.chat-batch>details{border-top:1px solid #d3e0f1;padding:10px 0}.chat-day{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:15px}.chat-day h4{margin-top:8px}.chat-day p{font-size:12px}.chat-day strong{margin-right:7px}.chat-composer{border:1px solid #b9cde6;background:white;padding:20px;border-radius:16px;margin:25px 0}.chat-composer textarea{border:0;min-height:100px;resize:vertical;padding:5px 0}.chat-composer .actions{justify-content:space-between}.photo-preview{display:flex;gap:15px;margin-bottom:15px}.photo-preview img{width:110px;height:110px;object-fit:cover;border-radius:8px}.photo-preview>div{min-width:0}.photo-preview p{font-size:12px;overflow-wrap:anywhere}.photo-preview small{font-size:10px}.photo-fields{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin:20px 0}.assistant-bubble details{overflow-wrap:anywhere}@media(max-width:640px){.chat-heading h2{font-size:18px}.assistant-bubble{padding:16px;margin-right:0}.user-bubble{margin-left:10%}.chat-batch,.chat-photo-result{padding:13px}.chat-day{grid-template-columns:1fr}.chat-composer{padding:15px}.photo-fields{grid-template-columns:1fr 1fr}.photo-fields label:first-child{grid-column:1/-1}.photo-preview img{width:85px;height:85px}.chat-heading>svg{display:none}.chat-batch button{font-size:12px;padding:9px 10px}}</style>
